# Names and vault references only -- never values. Resolved at run time by
# pass-cli into the provisioner's process, then discarded.
#
# Format: ENV_VAR=pass://<vault>/<item>/<field>
# A reference that does not resolve is reported and its step degrades to SKIP.
#
# Note: TS_OAUTH_SECRET is deliberately NOT here. Tailscale is the root of
# trust and runs before the vault is reachable, so it cannot come from the
# vault. Supply it as an environment variable for unattended provisioning.

GH_TOKEN=pass://dev/github/pat
CLAUDE_CODE_OAUTH_TOKEN=pass://dev/anthropic/claude-code-token
ELEVENLABS_API_KEY=pass://dev/g2/elevenlabs
OPENROUTER_API_KEY=pass://dev/g2/openrouter
